  KEY `fk_lotes_producto` (`id_producto`),
  KEY `idx_lotes_vencimiento` (`fecha_vencimiento`),
  CONSTRAINT `fk_lotes_producto` FOREIGN KEY (`id_producto`) REFERENCES `productos` (`id`) ON DELETE CASCADE
